// Phase 6: WebSocket Protocol
// RFC 6455 핸드쉐이크 및 프레임 처리

struct WebSocketFrame {
    opcode: i32,           // 1=text, 8=close, 9=ping, 10=pong
    payload: String,
    is_masked: bool,
    fin: bool              // 최종 프레임 여부
}

trait WebSocketFrameCl {
    fn clone(&self) -> WebSocketFrame;
}

impl WebSocketFrameCl for WebSocketFrame {
    fn clone(&self) -> WebSocketFrame {
        WebSocketFrame {
            opcode: self.opcode.clone(),
            payload: self.payload.clone(),
            is_masked: self.is_masked.clone(),
            fin: self.fin.clone()
        }
    }
}

// WebSocket 핸드쉐이크 검증
fn perform_websocket_handshake(request_headers: String) -> String {
    // "Upgrade: websocket" 헤더 확인
    if request_headers.contains("Upgrade: websocket") || request_headers.contains("Upgrade:") && request_headers.contains("websocket") {
        // 101 Switching Protocols 응답
        let mut response = String::new();
        response.push_str("HTTP/1.1 101 Switching Protocols\r\n");
        response.push_str("Upgrade: websocket\r\n");
        response.push_str("Connection: Upgrade\r\n");
        response.push_str("Sec-WebSocket-Accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOo=\r\n");
        response.push_str("\r\n");
        response
    } else {
        // 400 Bad Request
        let mut response = String::new();
        response.push_str("HTTP/1.1 400 Bad Request\r\n");
        response.push_str("Content-Type: text/plain\r\n");
        response.push_str("\r\n");
        response.push_str("Missing WebSocket upgrade header");
        response
    }
}

// WebSocket 프레임 파싱 (단순화된 구현)
fn parse_ws_frame(raw: String) -> WebSocketFrame {
    // 첫 문자로 opcode 판별 (실제 바이너리 프레임은 더 복잡)
    let opcode = if raw.len() > 0 && (raw.as_bytes()[0] as i32) == 49i32 { // '1' = text
        1i32
    } else if raw.len() > 0 && (raw.as_bytes()[0] as i32) == 56i32 { // '8' = close
        8i32
    } else if raw.len() > 0 && (raw.as_bytes()[0] as i32) == 57i32 { // '9' = ping
        9i32
    } else {
        1i32 // 기본값: text
    };

    // "opcode:payload" 형식으로 파싱
    let parts: Vec<String> = if raw.contains(":") {
        raw.split(":").map(|s| s.to_string()).collect()
    } else {
        vec![raw.clone()]
    };

    let payload = if parts.len() > 1 {
        parts[1].clone()
    } else {
        "".to_string()
    };

    WebSocketFrame {
        opcode: opcode,
        payload: payload,
        is_masked: false,
        fin: true
    }
}

// WebSocket 프레임 인코딩
fn encode_ws_frame(data: String, opcode: i32) -> String {
    // 단순화: JSON 데이터를 텍스트 프레임으로 래핑
    let mut frame = String::new();
    frame.push_str(&opcode.to_string());
    frame.push_str(":");
    frame.push_str(data.as_str());
    frame
}

// 프레임이 텍스트인지 확인
fn is_text_opcode(frame: WebSocketFrame) -> bool {
    frame.opcode == 1i32
}

// 프레임이 핑인지 확인
fn is_ping_opcode(frame: WebSocketFrame) -> bool {
    frame.opcode == 9i32
}

// 프레임이 클로즈인지 확인
fn is_close_opcode(frame: WebSocketFrame) -> bool {
    frame.opcode == 8i32
}

// 핸드쉐이크 응답이 성공인지 확인
fn is_handshake_success(response: String) -> bool {
    response.contains("101")
}

// 핸드쉐이크 응답이 실패인지 확인
fn is_handshake_failure(response: String) -> bool {
    response.contains("400")
}

