// Phase 6: WebSocket Connection Pool
// 활성 WebSocket 연결 관리

use crate::phase6::websocket_protocol::*;

struct WebSocketConnection {
    conn_id: i32,
    client_id: String,
    connected_at: String,
    last_ping: String,
    is_active: bool
}

trait WebSocketConnectionCl {
    fn clone(&self) -> WebSocketConnection;
}

impl WebSocketConnectionCl for WebSocketConnection {
    fn clone(&self) -> WebSocketConnection {
        WebSocketConnection {
            conn_id: self.conn_id.clone(),
            client_id: self.client_id.clone(),
            connected_at: self.connected_at.clone(),
            last_ping: self.last_ping.clone(),
            is_active: self.is_active.clone()
        }
    }
}

struct ConnectionPool {
    connections: Vec<WebSocketConnection>,
    next_conn_id: i32,
    max_connections: i32
}

trait ConnectionPoolCl {
    fn clone(&self) -> ConnectionPool;
}

impl ConnectionPoolCl for ConnectionPool {
    fn clone(&self) -> ConnectionPool {
        let mut cloned_connections = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.connections.len() as i32) { break; }
            cloned_connections.push(self.connections[(i as usize)].clone());
            i = i + 1i32;
        }

        ConnectionPool {
            connections: cloned_connections,
            next_conn_id: self.next_conn_id.clone(),
            max_connections: self.max_connections.clone()
        }
    }
}

// 연결 풀 생성
fn create_connection_pool(max: i32) -> ConnectionPool {
    ConnectionPool {
        connections: vec![],
        next_conn_id: 1i32,
        max_connections: max
    }
}

// 새로운 WebSocket 연결 추가
fn add_connection(pool: ConnectionPool, client_id: String) -> ConnectionPool {
    let new_conn = WebSocketConnection {
        conn_id: pool.next_conn_id,
        client_id: client_id,
        connected_at: "2026-03-18T12:00:00Z".to_string(),
        last_ping: "2026-03-18T12:00:00Z".to_string(),
        is_active: true
    };

    let mut new_connections = vec![];
    let mut i = 0i32;
    loop {
        if i >= (pool.connections.len() as i32) { break; }
        new_connections.push(pool.connections[(i as usize)].clone());
        i = i + 1i32;
    }
    new_connections.push(new_conn);

    ConnectionPool {
        connections: new_connections,
        next_conn_id: pool.next_conn_id + 1i32,
        max_connections: pool.max_connections
    }
}

// 연결 제거
fn remove_connection(pool: ConnectionPool, conn_id: i32) -> ConnectionPool {
    let mut new_connections = vec![];
    let mut i = 0i32;
    loop {
        if i >= (pool.connections.len() as i32) { break; }
        let conn = pool.connections[(i as usize)].clone();
        if conn.conn_id != conn_id {
            new_connections.push(conn);
        }
        i = i + 1i32;
    }

    ConnectionPool {
        connections: new_connections,
        next_conn_id: pool.next_conn_id,
        max_connections: pool.max_connections
    }
}

// 활성 연결 수 계산
fn get_active_count(pool: ConnectionPool) -> i32 {
    let mut count = 0i32;
    let mut i = 0i32;
    loop {
        if i >= (pool.connections.len() as i32) { break; }
        let conn = pool.connections[(i as usize)].clone();
        if conn.is_active {
            count = count + 1i32;
        }
        i = i + 1i32;
    }
    count
}

// 모든 연결 ID 목록
fn get_all_connection_ids(pool: ConnectionPool) -> Vec<i32> {
    let mut ids = vec![];
    let mut i = 0i32;
    loop {
        if i >= (pool.connections.len() as i32) { break; }
        ids.push(pool.connections[(i as usize)].conn_id);
        i = i + 1i32;
    }
    ids
}

// 연결이 가득 찼는지 확인
fn is_pool_full(pool: ConnectionPool) -> bool {
    (pool.connections.len() as i32) >= pool.max_connections
}

// 마지막 핑 업데이트
fn update_last_ping(pool: ConnectionPool, conn_id: i32) -> ConnectionPool {
    let mut new_connections = vec![];
    let mut i = 0i32;
    loop {
        if i >= (pool.connections.len() as i32) { break; }
        let mut conn = pool.connections[(i as usize)].clone();
        if conn.conn_id == conn_id {
            conn = WebSocketConnection {
                conn_id: conn.conn_id,
                client_id: conn.client_id.clone(),
                connected_at: conn.connected_at.clone(),
                last_ping: "2026-03-18T12:00:10Z".to_string(),
                is_active: conn.is_active
            };
        }
        new_connections.push(conn);
        i = i + 1i32;
    }

    ConnectionPool {
        connections: new_connections,
        next_conn_id: pool.next_conn_id,
        max_connections: pool.max_connections
    }
}

// 특정 연결 찾기
fn find_connection(pool: ConnectionPool, conn_id: i32) -> String {
    let mut i = 0i32;
    loop {
        if i >= (pool.connections.len() as i32) { break; }
        let conn = pool.connections[(i as usize)].clone();
        if conn.conn_id == conn_id {
            let mut json = String::new();
            json.push_str("{\"conn_id\":");
            json.push_str(&conn.conn_id.to_string());
            json.push_str(",\"client_id\":\"");
            json.push_str(conn.client_id.as_str());
            json.push_str("\",\"is_active\":");
            json.push_str(if conn.is_active { "true" } else { "false" });
            json.push_str("}");
            return json;
        }
        i = i + 1i32;
    }
    "{}".to_string()
}

