// ===== Group A: WebSocket 핸드쉐이크 (4개) =====

test "ws_handshake_valid_upgrade_header" {
    let headers = "GET /ws HTTP/1.1\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n".to_string();
    let response = perform_websocket_handshake(headers);
    assert response.contains("101");
    assert response.contains("Switching Protocols");
}

test "ws_handshake_missing_upgrade_returns_400" {
