    assert broadcaster.subscription_count == 0i32;

    let conn = WebSocketConnection {
        conn_id: 1i32,
        client_id: "client-1".to_string(),
        connected_at: "2026-03-18T12:00:00Z".to_string(),
        last_ping: "2026-03-18T12:00:00Z".to_string(),
        is_active: true
    };

    let b2 = add_connection(broadcaster, conn);
    assert b2.subscription_count == 1i32;
}

test "broadcaster_emit_event_increments_sent_count" {
    let broadcaster = create_broadcaster();
    assert broadcaster.total_events_sent == 0i32;

    let event = BroadcastEvent {
        event_type: "pipeline_complete".to_string(),
        payload: "{\"status\":\"ok\"}".to_string(),
        timestamp: "2026-03-18T12:00:00Z".to_string(),
        target_conn_id: -1i32
    };

    let b2 = broadcast_event(broadcaster, event);
    assert b2.total_events_sent == 1i32;
}

test "broadcaster_get_pending_events_returns_json_array" {
    let broadcaster = create_broadcaster();
    let event = BroadcastEvent {
        event_type: "test_event".to_string(),
        payload: "{}".to_string(),
        timestamp: "2026-03-18T12:00:00Z".to_string(),
        target_conn_id: -1i32
    };
    let b2 = broadcast_event(broadcaster, event);

    let json = get_pending_events_json(b2, 1i32);
    assert json.contains("test_event");
    assert json.contains("[");
    assert json.contains("]");
}

test "broadcaster_stats_json_contains_metrics" {
    let broadcaster = create_broadcaster();
    let stats = broadcaster_stats_json(broadcaster);
    assert stats.contains("subscription_count");
    assert stats.contains("total_events_sent");
    assert stats.contains("event_queue_size");
}

// ===== Group C: 연결 관리 (4개) =====

test "connection_pool_add_increments_next_id" {
    let pool = create_connection_pool(100i32);
    assert pool.next_conn_id == 1i32;

    let conn = WebSocketConnection {
        conn_id: 1i32,
        client_id: "client-1".to_string(),
        connected_at: "2026-03-18T12:00:00Z".to_string(),
        last_ping: "2026-03-18T12:00:00Z".to_string(),
        is_active: true
    };

    let p2 = add_connection(pool, "client-1".to_string());
    assert p2.next_conn_id == 2i32;
}

test "connection_pool_active_count_correct" {
    let pool = create_connection_pool(100i32);
    let conn = WebSocketConnection {
        conn_id: 1i32,
        client_id: "client-1".to_string(),
        connected_at: "2026-03-18T12:00:00Z".to_string(),
        last_ping: "2026-03-18T12:00:00Z".to_string(),
        is_active: true
    };
    let p2 = add_connection(pool, "client-1".to_string());

    let count = get_active_count(p2);
    assert count == 1i32;
}

test "connection_pool_remove_decreases_count" {
    let pool = create_connection_pool(100i32);
    let p2 = add_connection(pool, "client-1".to_string());
    assert get_active_count(p2) == 1i32;

