    let server = create_realtime_server();
    let result_json = "{\"status\":\"ok\",\"patches\":5}".to_string();
    let server2 = emit_pipeline_event(server, result_json);

    assert server2.broadcaster.total_events_sent == 1i32;
    assert server2.broadcaster.event_queue.len() > 0;
}

