// Phase 7: SQL Query Builder
// SQL 쿼리 문자열 생성 (push_str 기반)

use crate::phase7::db_schema::*;

struct QueryResult {
    rows: Vec<String>,
    column_names: Vec<String>,
    row_count: i32,
    success: bool,
    error_message: String
}

trait QueryResultCl {
    fn clone(&self) -> QueryResult;
}

impl QueryResultCl for QueryResult {
    fn clone(&self) -> QueryResult {
        let mut cloned_rows = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.rows.len() as i32) { break; }
            cloned_rows.push(self.rows[(i as usize)].clone());
            i = i + 1i32;
        }

        let mut cloned_columns = vec![];
        let mut j = 0i32;
        loop {
            if j >= (self.column_names.len() as i32) { break; }
            cloned_columns.push(self.column_names[(j as usize)].clone());
            j = j + 1i32;
        }

        QueryResult {
            rows: cloned_rows,
            column_names: cloned_columns,
            row_count: self.row_count.clone(),
            success: self.success.clone(),
            error_message: self.error_message.clone()
        }
    }
}

struct SelectBuilder {
    table: String,
    columns: Vec<String>,
    conditions: Vec<String>,
    limit_val: i32,
    order_by: String
}

trait SelectBuilderCl {
    fn clone(&self) -> SelectBuilder;
}

impl SelectBuilderCl for SelectBuilder {
    fn clone(&self) -> SelectBuilder {
        let mut cloned_columns = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.columns.len() as i32) { break; }
            cloned_columns.push(self.columns[(i as usize)].clone());
            i = i + 1i32;
        }

        let mut cloned_conditions = vec![];
        let mut j = 0i32;
        loop {
            if j >= (self.conditions.len() as i32) { break; }
            cloned_conditions.push(self.conditions[(j as usize)].clone());
            j = j + 1i32;
        }

        SelectBuilder {
            table: self.table.clone(),
            columns: cloned_columns,
            conditions: cloned_conditions,
            limit_val: self.limit_val.clone(),
            order_by: self.order_by.clone()
        }
    }
}

// INSERT 쿼리 생성
fn build_insert_query(table: String, fields: Vec<String>, values: Vec<String>) -> String {
    let mut sql = String::new();
    sql.push_str("INSERT INTO ");
    sql.push_str(table.as_str());
    sql.push_str(" (");

    let mut i = 0i32;
    loop {
        if i >= (fields.len() as i32) { break; }
        sql.push_str(fields[(i as usize)].as_str());
        if i < (fields.len() as i32) - 1i32 { sql.push_str(", "); }
        i = i + 1i32;
    }

    sql.push_str(") VALUES (");

    let mut j = 0i32;
    loop {
        if j >= (values.len() as i32) { break; }
        sql.push_str(values[(j as usize)].as_str());
        if j < (values.len() as i32) - 1i32 { sql.push_str(", "); }
        j = j + 1i32;
    }

    sql.push_str(");");
    sql
}

// SELECT 쿼리 생성
fn build_select_query(table: String, conditions: Vec<String>, limit: i32) -> String {
    let mut sql = String::new();
    sql.push_str("SELECT * FROM ");
    sql.push_str(table.as_str());

    if conditions.len() > 0i32 {
        sql.push_str(" WHERE ");
        let mut i = 0i32;
        loop {
            if i >= (conditions.len() as i32) { break; }
            sql.push_str(conditions[(i as usize)].as_str());
            if i < (conditions.len() as i32) - 1i32 { sql.push_str(" AND "); }
            i = i + 1i32;
        }
    }

    if limit > 0i32 {
        sql.push_str(" LIMIT ");
        sql.push_str(&limit.to_string());
    }

    sql.push_str(";");
    sql
}

// UPDATE 쿼리 생성
fn build_update_query(table: String, sets: Vec<String>, where_clause: String) -> String {
    let mut sql = String::new();
    sql.push_str("UPDATE ");
    sql.push_str(table.as_str());
    sql.push_str(" SET ");

    let mut i = 0i32;
    loop {
        if i >= (sets.len() as i32) { break; }
        sql.push_str(sets[(i as usize)].as_str());
        if i < (sets.len() as i32) - 1i32 { sql.push_str(", "); }
        i = i + 1i32;
    }

    if where_clause.len() > 0i32 {
        sql.push_str(" WHERE ");
        sql.push_str(where_clause.as_str());
    }

    sql.push_str(";");
    sql
}

// DELETE 쿼리 생성
fn build_delete_query(table: String, where_clause: String) -> String {
    let mut sql = String::new();
    sql.push_str("DELETE FROM ");
    sql.push_str(table.as_str());
    if where_clause.len() > 0i32 {
        sql.push_str(" WHERE ");
        sql.push_str(where_clause.as_str());
    }
    sql.push_str(";");
    sql
}

// 빈 QueryResult 생성
fn create_empty_query_result() -> QueryResult {
    QueryResult {
        rows: vec![],
        column_names: vec![],
        row_count: 0i32,
        success: false,
        error_message: "No data".to_string()
    }
}

// 성공 QueryResult 생성
fn create_success_query_result(rows: Vec<String>) -> QueryResult {
    QueryResult {
        rows: rows,
        column_names: vec![],
        row_count: (rows.len() as i32),
        success: true,
        error_message: "".to_string()
    }
}

// 실패 QueryResult 생성
fn create_error_query_result(error: String) -> QueryResult {
    QueryResult {
        rows: vec![],
        column_names: vec![],
        row_count: 0i32,
        success: false,
        error_message: error
    }
}

