// Phase 8: Tenant Manager
// 테넌트 CRUD 및 격리 관리

use crate::phase8::resource_quota::*;
use crate::phase8::tenant_context::*;

struct Tenant {
    tenant_id: String,
    name: String,
    api_key: String,
    created_at: String,
    status: String,                  // "active", "inactive", "suspended"
    quota: ResourceQuota
}

trait TenantCl {
    fn clone(&self) -> Tenant;
}

impl TenantCl for Tenant {
    fn clone(&self) -> Tenant {
        Tenant {
            tenant_id: self.tenant_id.clone(),
            name: self.name.clone(),
            api_key: self.api_key.clone(),
            created_at: self.created_at.clone(),
            status: self.status.clone(),
            quota: self.quota.clone()
        }
    }
}

struct TenantManager {
    tenants: Vec<Tenant>,
    active_count: i32,
    next_tenant_num: i32
}

trait TenantManagerCl {
    fn clone(&self) -> TenantManager;
}

impl TenantManagerCl for TenantManager {
    fn clone(&self) -> TenantManager {
        let mut cloned_tenants = vec![];
        let mut i = 0i32;
        loop {
            if i >= (self.tenants.len() as i32) { break; }
            cloned_tenants.push(self.tenants[(i as usize)].clone());
            i = i + 1i32;
        }

        TenantManager {
            tenants: cloned_tenants,
            active_count: self.active_count.clone(),
            next_tenant_num: self.next_tenant_num.clone()
        }
    }
}

// 테넌트 매니저 생성
fn create_tenant_manager() -> TenantManager {
    TenantManager {
        tenants: vec![],
        active_count: 0i32,
        next_tenant_num: 1i32
    }
}

