// Phase 8: Workspace Router
// 테넌트별 요청 라우팅 및 격리

use crate::phase5::http_server::*;
use crate::phase8::tenant_manager::*;
use crate::phase8::tenant_context::*;
use crate::phase8::resource_quota::*;

struct WorkspaceRouter {
    tenant_manager: TenantManager,
    route_count: i32,
    rejected_count: i32
}

trait WorkspaceRouterCl {
    fn clone(&self) -> WorkspaceRouter;
}

impl WorkspaceRouterCl for WorkspaceRouter {
    fn clone(&self) -> WorkspaceRouter {
        WorkspaceRouter {
            tenant_manager: self.tenant_manager.clone(),
            route_count: self.route_count.clone(),
            rejected_count: self.rejected_count.clone()
        }
    }
}

// 워크스페이스 라우터 생성
fn create_workspace_router() -> WorkspaceRouter {
    WorkspaceRouter {
        tenant_manager: create_tenant_manager(),
        route_count: 0i32,
        rejected_count: 0i32
    }
}

// 요청 인증
fn authenticate_request(router: WorkspaceRouter, req: HttpRequest) -> (bool, String) {
    let api_key = extract_api_key(req);
    let tenant_id = find_tenant_by_key(router.tenant_manager.clone(), api_key);

    if tenant_id.len() > 0i32 {
        (true, tenant_id)
    } else {
        (false, "".to_string())
    }
}

// 테넌트별 요청 라우팅
fn route_request_by_tenant(router: WorkspaceRouter, req: HttpRequest, tenant_id: String) -> (HttpResponse, WorkspaceRouter) {
    // 테넌트 ID 검증
    if tenant_id.len() == 0i32 {
        let response = HttpResponse {
            status_code: 401i32,
            status_text: "Unauthorized".to_string(),
            content_type: "application/json".to_string(),
            body: "{\"error\":\"Missing tenant ID\"}".to_string()
        };

        let new_router = WorkspaceRouter {
            tenant_manager: router.tenant_manager.clone(),
            route_count: router.route_count,
            rejected_count: router.rejected_count + 1i32
        };

        return (response, new_router);
    }

    // 테넌트 정보 조회
    let tenant_json = get_tenant_by_id(router.tenant_manager.clone(), tenant_id.clone());
    if tenant_json == "{}".to_string() {
        let response = HttpResponse {
            status_code: 403i32,
            status_text: "Forbidden".to_string(),
            content_type: "application/json".to_string(),
            body: "{\"error\":\"Tenant not found\"}".to_string()
        };

        let new_router = WorkspaceRouter {
            tenant_manager: router.tenant_manager.clone(),
            route_count: router.route_count,
            rejected_count: router.rejected_count + 1i32
        };

        return (response, new_router);
    }

    // 정상 요청: 200 OK 응답
    let response = HttpResponse {
        status_code: 200i32,
        status_text: "OK".to_string(),
        content_type: "application/json".to_string(),
        body: tenant_json
    };

    let new_router = WorkspaceRouter {
        tenant_manager: router.tenant_manager.clone(),
        route_count: router.route_count + 1i32,
        rejected_count: router.rejected_count
    };

    (response, new_router)
}

// 테넌트 관리자 엔드포인트 처리
fn handle_tenant_admin(req: HttpRequest, router: WorkspaceRouter) -> (HttpResponse, WorkspaceRouter) {
    if req.path == "/admin/tenants".to_string() {
        let tenants_json = list_active_tenants_json(router.tenant_manager.clone());

        let response = HttpResponse {
            status_code: 200i32,
            status_text: "OK".to_string(),
            content_type: "application/json".to_string(),
            body: tenants_json
        };

        (response, router)
    } else {
        let response = HttpResponse {
            status_code: 404i32,
            status_text: "Not Found".to_string(),
            content_type: "text/plain".to_string(),
            body: "Admin endpoint not found".to_string()
        };

        (response, router)
    }
}

// 워크스페이스 라우터 실행
fn run_multitenant_server() {
    println!("Sovereign Workspace Phase 8: Multi-tenant Server");
    println!("Tenant Endpoints:");
    println!("  POST /auth              - Authenticate with API key");
    println!("  GET  /admin/tenants     - List all active tenants");
    println!("  GET  /tenant/{id}       - Get tenant details");
    println!("All requests require tenant_id parameter");
}

// 테넌트별 요청 수 조회
fn get_router_stats(router: WorkspaceRouter) -> String {
    let mut json = String::new();
    json.push_str("{\"route_count\":");
    json.push_str(&router.route_count.to_string());
    json.push_str(",\"rejected_count\":");
    json.push_str(&router.rejected_count.to_string());
    json.push_str(",\"tenant_count\":");
    json.push_str(&get_tenant_count(router.tenant_manager.clone()).to_string());
    json.push_str("}");
    json
}

