// ===== Group A: 스키마 생성 (4개) =====

test "schema_creates_valid_create_table_sql" {
    let config = create_db_config("test.db".to_string());
    let sql = initialize_schema(config);
    assert sql.contains("CREATE TABLE");
    assert sql.contains("execution_records");
}

test "schema_contains_all_columns" {
    let config = create_db_config(":memory:".to_string());
    let sql = initialize_schema(config);
    assert sql.contains("record_id");
    assert sql.contains("user_intent");
    assert sql.contains("healing_success_rate");
}

test "schema_contains_autoincrement" {
    let config = create_db_config("test.db".to_string());
    let sql = initialize_schema(config);
    assert sql.contains("AUTOINCREMENT");
}

test "schema_contains_defaults" {
    let config = create_db_config("test.db".to_string());
    let sql = initialize_schema(config);
    assert sql.contains("DEFAULT");
}

// ===== Group B: 쿼리 빌더 (5개) =====

test "query_builder_insert_contains_values_keyword" {
    let fields = vec!["user_intent".to_string(), "success".to_string()];
    let values = vec!["'test'".to_string(), "1".to_string()];
    let sql = build_insert_query("execution_records".to_string(), fields, values);
    assert sql.contains("INSERT INTO");
    assert sql.contains("VALUES");
}

test "query_builder_select_contains_from" {
    let conditions = vec![];
